/**
 * IMDb / Amazon poster CDN, requested as a 500px-wide 2:3 crop so every card in
 * the grid keeps an identical aspect ratio.
 */
export function remotePoster(slug: string): string | undefined {
  const id = imdbIds[slug];
  if (!id) return undefined;
  return `https://m.media-amazon.com/images/M/${id}._V1_QL75_UX500_CR0,0,500,741_.jpg`;
}

export function hasRemotePoster(slug: string) {
  return slug in imdbIds;
}
